content.text:
            for k in range(j, m):
                if pos in uses[k]:
                    c += 1
            row[pos] = c
        remaining.append(row)
    if m:
        walk(0, pinned_benefit, pinned_count)
    return state["set"]


# ---------------------------------------------------------------------- driver

def _respond(line):
    obj = _load_object(line)
    mode = obj.get("mode")
    if mode == "replay":
        return _handle_replay(obj)
    if mode == "plan":
        return _handle_plan(obj)
    raise Bad("bad mode")


def main():
    out = sys.stdout.buffer
    inp = sys.stdin.buffer
    write = out.write
    dumps = json.dumps
    for raw in inp:
        try:
            if len(raw) > _MAX_LINE:
                raise Bad("line too long")
            line = raw.decode("utf-8")
            response = _respond(line)
        except Bad:
            response = _INPUT_ERROR
        except Exception:
            response = _INPUT_ERROR
        write(dumps(response, separators=(",", ":")).encode("ascii"))
        write(b"\n")
    try:
        out.flush()
